// 📁 src/layout/AdminLayout.jsx
import { useEffect, useState } from "react";
import { Outlet, useNavigate, useLocation } from "react-router-dom";
import { jwtDecode } from "jwt-decode";
import { Menu, Loader2 } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import AdminSidebar from "@/components/admin/AdminSidebar";
import NavbarAdmin from "@/components/NavbarAdmin";
import toast from "react-hot-toast";

const AdminLayout = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { logout, admin, initialCheckDone } = useAuth();

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [email, setEmail] = useState("");

  const isLoginPage = location.pathname === "/admin/login";

  // ✅ Loader temporaire pendant vérification de session
  if (!initialCheckDone && !isLoginPage) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-gray-900">
        <Loader2 className="animate-spin h-6 w-6 text-red-600 dark:text-white" />
        <span className="ml-2 text-gray-700 dark:text-white">
          Vérification de session admin...
        </span>
      </div>
    );
  }

  // 🔒 Redirection si non connecté
  useEffect(() => {
    if (initialCheckDone && !admin && !isLoginPage) {
      navigate("/admin/login");
    }
  }, [admin, initialCheckDone, isLoginPage, navigate]);

  // 📧 Extraire email à partir du token
  useEffect(() => {
    const token =
      localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        if (decoded?.email) {
          setEmail(decoded.email);
        } else {
          throw new Error("Token invalide");
        }
      } catch (err) {
        console.error("⛔ Erreur de décodage du token :", err.message);
        logout();
        navigate("/admin/login");
      }
    }
  }, [navigate, logout]);

  // ⏰ Déconnexion auto après inactivité
  useEffect(() => {
    const timeout = 15 * 60 * 1000; // 15 minutes
    let logoutTimer;

    const resetTimer = () => {
      clearTimeout(logoutTimer);
      logoutTimer = setTimeout(() => {
        toast.error("⏳ Session expirée après 15 min d'inactivité.");
        logout();
        navigate("/admin/login");
      }, timeout);
    };

    resetTimer();
    window.addEventListener("mousemove", resetTimer);
    window.addEventListener("keydown", resetTimer);

    return () => {
      window.removeEventListener("mousemove", resetTimer);
      window.removeEventListener("keydown", resetTimer);
      clearTimeout(logoutTimer);
    };
  }, [logout, navigate]);

  const handleLogout = () => {
    logout();
    navigate("/admin/login");
  };

  return (
    <div className="flex h-screen">
      {!isLoginPage && (
        <aside
          className={`fixed z-40 top-0 left-0 h-full w-64 bg-white dark:bg-gray-800 shadow-lg px-4 py-6 transform ${
            sidebarOpen ? "translate-x-0" : "-translate-x-full"
          } transition-transform duration-300 md:relative md:translate-x-0`}
        >
          <AdminSidebar email={email} onLogout={handleLogout} />
        </aside>
      )}

      {!isLoginPage && (
        <button
          onClick={() => setSidebarOpen(true)}
          className="md:hidden fixed top-4 left-4 z-50 bg-white dark:bg-gray-800 shadow p-2 rounded-full"
        >
          <Menu size={24} />
        </button>
      )}

      <div className={`flex-1 flex flex-col ml-0 ${!isLoginPage ? "md:ml-64" : ""}`}>
        {!isLoginPage && <NavbarAdmin />}
        <main className="flex-1 bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white p-6 overflow-y-auto">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default AdminLayout;
